input.command:
cat > config.json << 'EOF'
{
  "name": "GraphQL Migration RFC",
  "description": "Technical RFC proposing switch from REST to GraphQL for client-facing APIs, with motivation, approach, projects/tasks schema sketch, and open questions."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "rfc_writer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "GraphQL RFC API Design Review",
  "description": "Reviews the GraphQL Migration RFC for API design quality across schema complexity, query limits, pagination, error handling, and REST compatibility, delivering per-area verdicts and an overall recommendation."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "reviewer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "GraphQL Performance Review",
  "description": "Analyzes the GraphQL Migration RFC for performance risks including N+1 queries, payload sizes, caching strategies, and latency impacts, with quantified estimates, per-area verdicts, and overall recommendation."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "reviewer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "GraphQL Security Review",
  "description": "Security evaluation of the GraphQL Migration RFC, assessing query complexity limits, authorization model, introspection exposure, rate limiting, and custom scalar injection risks, with verdicts per area and an overall recommendation."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "security_reviewer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "DevEx Review",
  "description": "Developer experience evaluation of GraphQL migration RFC, assessing client codegen, type safety, docs, testing, and migration impact with verdicts and overall recommendation."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "devex_reviewer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "Review Synthesis and Conflict Resolution",
  "description": "Synthesizes API, Performance, and Security reviews into a conflict resolution document tabulating verdicts per area, summarizing consensus, resolving disagreements with proposed mitigations, and assigning action items."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "synthesizer": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "GraphQL Migration Plan",
  "description": "Phased migration timeline from REST to GraphQL based on DX review, detailing deliverables, team responsibilities, rollback triggers, and success metrics for each phase."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "planner": { "depends_on": [] }
  }
}
EOF

cat > config.json << 'EOF'
{
  "name": "Architecture Decision Record",
  "description": "Formal ADR for GraphQL migration synthesizing review conflicts, resolutions, migration plan, with consequences, compliance, and phase-linked references."
}
EOF

cat > topology.json << 'EOF'
{
  "agents": {
    "adr_writer": { "depends_on": [] }
  }
}
EOF
